const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key=new URLSearchParams(location.search).get('doc')||'process';
const data=artifactData[key]||artifactData.process;
const related=data.related.map(([label,href])=>`<a class="artifact-related-link" href="${href}">${esc(label)} <span>↗</span></a>`).join('');
const sections=data.sections.map(([heading,text],i)=>`<article class="artifact-detail-section"><span>0${i+1}</span><div><h3>${esc(heading)}</h3><p>${esc(text)}</p></div></article>`).join('');
const visual=data.visual?`<figure class="artifact-preview"><img src="${data.visual}" alt="${esc(data.visualAlt)}"><figcaption>${esc(data.format)}</figcaption></figure>`:'';
const fullDocument=window.MarginPilotDocumentContent?.[key]||'';
const sourceBlock=data.source&&!/\.md$/i.test(data.source)?`<div class="artifact-source"><small>ДОПОЛНИТЕЛЬНЫЙ ФОРМАТ</small><strong>${esc(data.sourceLabel)}</strong><a href="${data.source}">${esc(data.source)} ↗</a></div>`:'';
const sourceAction=fullDocument?'':`<a class="button primary" href="${data.source}">${esc(data.sourceLabel)} ↗</a>`;
document.title=`MarginPilot — ${data.title}`;
document.getElementById('artifact-root').innerHTML=`
  <section class="artifact-detail-hero"><div class="wrap"><a class="artifact-breadcrumb" href="artifacts.html">← Все артефакты</a><p class="kicker">${esc(data.kicker)}</p><h1>${esc(data.title)}</h1><p class="artifact-detail-lead">${esc(data.lead)}</p><div class="artifact-detail-meta"><span>${esc(data.layer)}</span><span>${esc(data.format)}</span></div></div></section>
  <section class="artifact-detail-content"><div class="wrap artifact-detail-grid"><div class="artifact-detail-copy"><div class="artifact-detail-intro"><p class="kicker">О чём этот артефакт</p><h2>Решение видно<br>через детали.</h2></div>${sections}${sourceAction}${fullDocument?`<section class="artifact-full-document"><div class="artifact-full-document-head"><p class="kicker">ПОЛНЫЙ ДОКУМЕНТ</p><h2>Материал целиком</h2></div><article class="document-body">${fullDocument}</article></section>`:''}</div><aside class="artifact-detail-side">${visual}${sourceBlock}<div class="artifact-related"><small>СВЯЗАННЫЕ МАТЕРИАЛЫ</small>${related}</div></aside></div></section>`;
